DELETE FROM products p WHERE p.sku ~ '^SKU-(ELEC|FASH|HOME|SPOR|BOOK|BEAU|GROC|ACCE)-[0-9]{3}$' AND NOT (p.sku IN ('SKU-ELEC-001', 'SKU-ELEC-002', 'SKU-ELEC-007', 'SKU-ELEC-014', 'SKU-ELEC-015', 'SKU-ELEC-018', 'SKU-ELEC-019', 'SKU-ELEC-020', 'SKU-ELEC-025', 'SKU-ELEC-026', 'SKU-ELEC-028', 'SKU-ELEC-034', 'SKU-ELEC-037', 'SKU-ELEC-038', 'SKU-ELEC-039', 'SKU-ELEC-041', 'SKU-ELEC-043', 'SKU-ELEC-044', 'SKU-FASH-001', 'SKU-FASH-002', 'SKU-FASH-004', 'SKU-FASH-005', 'SKU-FASH-006', 'SKU-FASH-008', 'SKU-FASH-011', 'SKU-FASH-014', 'SKU-FASH-015', 'SKU-FASH-016', 'SKU-FASH-017', 'SKU-FASH-027', 'SKU-FASH-029', 'SKU-FASH-031', 'SKU-FASH-034', 'SKU-FASH-037', 'SKU-FASH-045', 'SKU-FASH-055', 'SKU-HOME-001', 'SKU-HOME-002', 'SKU-HOME-003', 'SKU-HOME-004', 'SKU-HOME-005', 'SKU-HOME-007', 'SKU-HOME-008', 'SKU-HOME-011', 'SKU-HOME-012', 'SKU-HOME-013', 'SKU-HOME-015', 'SKU-HOME-016', 'SKU-HOME-017', 'SKU-HOME-019', 'SKU-HOME-020', 'SKU-HOME-023', 'SKU-HOME-024', 'SKU-HOME-059', 'SKU-SPOR-001', 'SKU-SPOR-002', 'SKU-SPOR-006', 'SKU-SPOR-007', 'SKU-SPOR-011', 'SKU-SPOR-012', 'SKU-SPOR-014', 'SKU-SPOR-015', 'SKU-SPOR-016', 'SKU-SPOR-017', 'SKU-SPOR-018', 'SKU-SPOR-020', 'SKU-SPOR-021', 'SKU-SPOR-023', 'SKU-SPOR-024', 'SKU-SPOR-025', 'SKU-SPOR-026', 'SKU-SPOR-027', 'SKU-BOOK-001', 'SKU-BOOK-003', 'SKU-BOOK-006', 'SKU-BOOK-007', 'SKU-BOOK-011', 'SKU-BOOK-012', 'SKU-BOOK-014', 'SKU-BOOK-016', 'SKU-BOOK-018', 'SKU-BOOK-019', 'SKU-BOOK-021', 'SKU-BOOK-022', 'SKU-BOOK-023', 'SKU-BOOK-025', 'SKU-BOOK-027', 'SKU-BOOK-029', 'SKU-BOOK-030', 'SKU-BOOK-037', 'SKU-BEAU-001', 'SKU-BEAU-002', 'SKU-BEAU-004', 'SKU-BEAU-008', 'SKU-BEAU-015', 'SKU-BEAU-016', 'SKU-BEAU-017', 'SKU-BEAU-018', 'SKU-BEAU-019', 'SKU-BEAU-025', 'SKU-BEAU-026', 'SKU-BEAU-028', 'SKU-BEAU-034', 'SKU-BEAU-051', 'SKU-BEAU-052', 'SKU-BEAU-053', 'SKU-BEAU-054', 'SKU-BEAU-058', 'SKU-GROC-001', 'SKU-GROC-003', 'SKU-GROC-005', 'SKU-GROC-006', 'SKU-GROC-008', 'SKU-GROC-010', 'SKU-GROC-013', 'SKU-GROC-014', 'SKU-GROC-015', 'SKU-GROC-017